const ctx = $input.first().json;
if (!ctx || !ctx.salao) return [];
const s = ctx.salao;
const c = ctx.cliente ?? {};
if (c.humano_ate && new Date(c.humano_ate) > new Date()) return [];
const duracao = m => { const h = Math.floor(m / 60), r = m % 60; return h ? `${h}h${r ? String(r).padStart(2, '0') : ''}` : `${r} min`; };
const preco = v => Number(v) > 0 ? `R$ ${Number(v).toFixed(2).replace('.', ',').replace(',00', '')}` : 'grátis';
const profissionais = (ctx.profissionais ?? []).map(p => `- ${p.nome}: ${p.funcao ?? ''}. ${p.dias_trabalho ?? ''}.`).join('\n');
const servicos = (ctx.servicos ?? []).map(v => `- ${v.nome}: ${duracao(v.duracao_min)}, ${preco(v.preco)}, ${(v.profissionais ?? []).join(' ou ')}${v.observacoes ? ` (${v.observacoes})` : ''}`).join('\n');
const agendamentos = (ctx.agendamentos ?? []).map(a => `- id ${a.id}: ${a.servico ?? 'serviço'} com ${a.profissional ?? 'profissional'}, ${a.quando} (${duracao(a.duracao_min)})${a.pode_alterar === false ? ' - FORA DO PRAZO para mudar pelo WhatsApp' : ''}`).join('\n');
const prazo = Number(s.antecedencia_minima_horas) > 0 ? `até ${s.antecedencia_minima_horas} horas antes do horário` : 'a qualquer momento antes do horário';
const base = [
  'SOBRE',
  `Endereço: ${s.endereco ?? ''}`,
  `Telefone: ${s.telefone ?? ''}`,
  `Funcionamento: ${s.funcionamento ?? ''}`,
  '',
  'PROFISSIONAIS',
  profissionais,
  '',
  'SERVIÇOS (duração, preço, profissional)',
  servicos,
  '',
  'GUIA PARA A TRIAGEM',
  s.guia_triagem ?? '',
  '',
  'POLÍTICAS',
  s.politicas ?? ''
].join('\n');
return [{ json: {
  salao_id: s.id,
  nome_negocio: s.nome,
  nome_assistente: s.nome_assistente,
  tipo_negocio: s.tipo_negocio,
  tom: s.tom,
  fuso: s.fuso,
  regras_especificas: s.regras_especificas ?? '',
  calendar_id: s.calendar_id ?? '',
  whatsapp_responsavel: s.whatsapp_responsavel ?? '',
  cliente_nome: c.nome ?? '',
  cliente_email: c.email ?? '',
  cliente_agendamentos: agendamentos || 'Nenhum',
  prazo_alteracao: prazo,
  base_conhecimento: base
} }];
